  1757	    fn backspace(self: *State) void {
  1758	        // buffer_length must be positive for backspace.
  1759	        assert(self.buffer_length > 0);
  1760	
  1761	        if (self.literal_index) |literal_index| {
  1762	            // literal_index must be within buffer_effective range when set.
  1763	            assert(literal_index < self.buffer_effective.len);
  1764	            // literal_index must be less than buffer_length.
  1765	            assert(literal_index < self.buffer_length);
  1766	        }
