  1768	        // decrease the buffer_length to match the backspace.
  1769	        self.buffer_length -= 1;
  1770	        // because backspace doesn't retro-modify the buffer, unset the buffer_modification_index.
  1771	        self.buffer_modification_index = null;
  1772	        // if the literal_index is out of buffer range, unset it.
  1773	        if (self.literal_index != null and self.literal_index.? == self.buffer_length) {
